"use client";

// Keep this entry independent of the eager barrel: no Three/R3F runtime imports.
import { Component, lazy, Suspense, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import type { ModelViewerProps } from "./model-viewer-types";
import { ViewerLoader } from "./viewer-loader";
import "./model-viewer.css";

export { ModelViewerSkeleton } from "./model-viewer-skeleton";
export type { ModelViewerSkeletonProps } from "./model-viewer-skeleton";

const Viewer = lazy(() => import("./model-viewer").then((module) => ({ default: module.ModelViewer })));

/**
 * Loads the renderer chunk only when mounted. Use this entry for optional embeds.
 * `loadingFallback` and `poster` cover the chunk download and model loading alike.
 */
export function ModelViewer(props: ModelViewerProps) {
  const { className, height, style, poster, loadingFallback, showFileName = false, src } = props;
  return (
    <ImportErrorBoundary className={className} height={height} style={style} onError={props.onError}>
      <Suspense fallback={
        <div data-slot="model-viewer-lazy" className={cn("model-viewer", className)} style={{ height, ...style }}>
          {poster && <img className="viewer-poster" src={poster} alt="" aria-hidden="true" />}
          <ViewerLoader fallback={loadingFallback} poster={Boolean(poster)} showFileName={showFileName} src={src} />
        </div>
      }>
        <Viewer {...props} />
      </Suspense>
    </ImportErrorBoundary>
  );
}

// This boundary lives outside the downloaded module, so it can handle a failed
// chunk request. Reloading also recovers stale chunk URLs after a deployment;
// remounting React.lazy alone would reuse its cached rejection.
class ImportErrorBoundary extends Component<
  Pick<ModelViewerProps, "className" | "height" | "style" | "onError"> & { children: ReactNode },
  { failed: boolean }
> {
  state = { failed: false };

  static getDerivedStateFromError() {
    return { failed: true };
  }

  componentDidCatch(error: Error) {
    this.props.onError?.(error);
  }

  render() {
    if (!this.state.failed) return this.props.children;
    const { className, height, style } = this.props;
    return (
      <div data-slot="model-viewer-lazy" className={cn("model-viewer", className)} style={{ height, ...style }}>
        <div className="viewer-loader" role="alert">
          <span>Unable to load the viewer.</span>
          <button type="button" className="underline underline-offset-4" onClick={() => window.location.reload()}>
            Reload page
          </button>
        </div>
      </div>
    );
  }
}

export type { ModelViewerProps } from "./model-viewer-types";

// Safe for the lazy entry: no Three/R3F runtime imports.
import type { ComponentProps } from "react";
import { cn } from "@/lib/utils";

export type ModelViewerSkeletonProps = ComponentProps<"div"> & {
  /** Placeholder blocks for the top toolbar. */
  showToolbar?: boolean;
  /** Placeholder block for the view cube. */
  showViewCube?: boolean;
  /** Screen-reader text, announced by the viewer loader's status region. Pass an empty string to omit it. */
  label?: string;
};

/**
 * Viewer-shaped placeholder. Fills its nearest positioned ancestor, so it works
 * as `loadingFallback` or inside any `.model-viewer` frame.
 */
export function ModelViewerSkeleton({
  showToolbar = true,
  showViewCube = true,
  label = "Loading 3D viewer…",
  className,
  ...props
}: ModelViewerSkeletonProps) {
  return (
    <div
      data-slot="model-viewer-skeleton"
      className={cn("viewer-skeleton", className)}
      {...props}
    >
      {showToolbar && (
        <div className="viewer-skeleton-toolbar">
          <span className="viewer-skeleton-block" style={{ width: 104 }} />
          <span className="viewer-skeleton-block" style={{ width: 72 }} />
          <span className="viewer-skeleton-block" style={{ width: 36 }} />
        </div>
      )}
      {showViewCube && <span className="viewer-skeleton-block viewer-skeleton-cube" />}
      <svg className="viewer-skeleton-model" viewBox="0 0 120 120" aria-hidden="true">
        <ellipse className="viewer-skeleton-shadow" cx="60" cy="108" rx="44" ry="8" />
        <path className="viewer-skeleton-face" d="M60 14 102 36 60 58 18 36Z" />
        <path className="viewer-skeleton-face is-left" d="M18 36 60 58v46L18 82Z" />
        <path className="viewer-skeleton-face is-right" d="M102 36 60 58v46l42-22Z" />
      </svg>
      {label && <span className="sr-only">{label}</span>}
    </div>
  );
}

"use client";

// Shared by the scene and the lazy entry: no Three/R3F runtime imports.
import { cn } from "@/lib/utils";
import type { ModelViewerProps } from "./model-viewer-types";
import { ViewerLoaderSpinner } from "./viewer-loader-spinner";

export function ViewerLoader({
  fallback,
  poster,
  showFileName,
  src,
}: {
  fallback?: ModelViewerProps["loadingFallback"];
  poster: boolean;
  showFileName: boolean;
  src?: string;
}) {
  // Drei's useProgress observes the global loading manager, which also tracks
  // assets belonging to other viewer instances. This is intentionally
  // indeterminate until this viewer's own scene reports ready or error.
  const data = { active: true, progress: 0, item: src ?? "", loaded: 0, total: 0 };
  const custom = typeof fallback === "function" ? fallback(data) : fallback;
  if (fallback !== undefined && custom == null) return null;
  return (
    <div
      className={cn("viewer-loader", poster && "has-poster")}
      role="status"
      aria-live="polite"
    >
      {fallback !== undefined ? (
        custom
      ) : (
        <>
          <ViewerLoaderSpinner />
          <span>Loading model…</span>
          {showFileName && src && <small>{fileName(src)}</small>}
        </>
      )}
    </div>
  );
}

function fileName(path: string) {
  return path.split(/[?#]/)[0].split(/[\\/]/).pop() || "Model asset";
}

"use client";

import { LoaderCircle } from "lucide-react";
import { useLayoutEffect, useRef } from "react";

/** Keeps the indeterminate loader's phase stable when one loading view replaces another. */
export function ViewerLoaderSpinner() {
  const spinner = useRef<SVGSVGElement>(null);

  useLayoutEffect(() => {
    const animation = spinner.current?.getAnimations()[0];
    if (animation) animation.startTime = 0;
  }, []);

  return (
    <LoaderCircle
      ref={spinner}
      className="viewer-loader-spinner"
      aria-hidden="true"
    />
  );
}

"use client";

import type { ComponentProps } from "react";
import { Compass } from "lucide-react";
import { cn } from "@/lib/utils";
import { DropdownMenu, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { DropdownMenuContent } from "./viewer-popups";
import { ViewerControlButton } from "./viewer-ui";
import { useViewerRuntime } from "./model-viewer-context";
import type { ViewerCameraPreset } from "./model-viewer-types";

const directions: ViewerCameraPreset[] = ["front", "right", "back", "left", "top", "bottom", "isometric"];

/** Keyboard counterpart to the canvas gizmo. Reveals itself when focused. */
export function ModelViewerOrientationControls({ className, ...props }: ComponentProps<"div">) {
  const { state, showOrientation } = useViewerRuntime();
  if (!showOrientation || !state.viewCube || state.mode !== "orbit" || state.status !== "ready") return null;
  return (
    <div data-slot="model-viewer-orientation" className={cn("viewer-orientation-controls", className)} {...props}>
      <DropdownMenu modal={false}>
        <DropdownMenuTrigger render={
          <ViewerControlButton aria-label="Orient view" variant="outline" size="sm">
            <Compass /> Orient view
          </ViewerControlButton>
        } />
        <DropdownMenuContent align="end">
          {directions.map((direction) => (
            <DropdownMenuItem key={direction} onClick={() => {
              state.setCameraPreset(direction);
              state.resetView();
            }}>
              {direction[0].toUpperCase() + direction.slice(1)} view
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

"use client";

import {
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import {
  Box,
  Camera,
  ChevronDown,
  CloudSun,
  Copy,
  Download,
  Footprints,
  Gauge,
  Grid2X2,
  Layers3,
  LayoutGrid,
  ListTree,
  Pause,
  Play,
  Rotate3D,
  RotateCcw,
  RotateCw,
  ScanSearch,
} from "lucide-react";
import { cn } from "@/lib/utils";
import {
  DropdownMenu,
  DropdownMenuItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { DropdownMenuContent } from "./viewer-popups";
import { ViewerControlButton as Button } from "./viewer-ui";
import { useOptionalViewerRuntime } from "./model-viewer-context";
import type {
  ViewerMode,
  ViewerLighting,
  ViewerShading,
  ViewerViewCube,
} from "./model-viewer";
import "./model-viewer.css";

const shadingLabels: Record<ViewerShading, string> = {
  realistic: "Realistic",
  solid: "Solid",
  normals: "Normals",
  wireframe: "Wireframe",
};

export function ModelViewerToolbar({
  className,
  onKeyDown,
  ref,
  placement = "top",
  ...props
}: ComponentProps<"div"> & { placement?: "top" | "animation" | "static" }) {
  const elementRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => elementRef.current!, []);
  const runtime = useOptionalViewerRuntime();
  const reportToolbar = runtime?.reportToolbar;
  const viewerRef = runtime?.viewerRef;
  useLayoutEffect(() => {
    const element = elementRef.current;
    if (!element || !reportToolbar || !viewerRef || placement !== "top") return;
    const measure = () => {
      const root = viewerRef.current;
      if (!root) return;
      const rect = element.getBoundingClientRect();
      reportToolbar(
        element,
        Math.ceil(rect.bottom - root.getBoundingClientRect().top + 12),
      );
    };
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    if (viewerRef.current) observer.observe(viewerRef.current);
    measure();
    return () => {
      observer.disconnect();
      reportToolbar(element, null);
    };
  }, [reportToolbar, viewerRef, placement, className, props.style]);
  return (
    <div
      ref={elementRef}
      data-slot="model-viewer-toolbar"
      role="toolbar"
      aria-label="3D viewer controls"
      className={cn(
        "viewer-toolbar",
        placement === "top" && "viewer-toolbar-top",
        placement === "animation" && "viewer-animation-controls",
        className,
      )}
      {...props}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (
          event.defaultPrevented ||
          event.altKey ||
          event.ctrlKey ||
          event.metaKey
        )
          return;
        if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key))
          return;
        // Ignore events from portaled menus and editable controls.
        const target = event.target as HTMLElement;
        if (!event.currentTarget.contains(target) || !target.closest("button"))
          return;
        const buttons = [
          ...event.currentTarget.querySelectorAll<HTMLButtonElement>(
            "button:not(:disabled)",
          ),
        ];
        const current = buttons.indexOf(target.closest("button")!);
        if (current < 0 || buttons.length === 0) return;
        const next =
          event.key === "Home"
            ? 0
            : event.key === "End"
              ? buttons.length - 1
              : (current +
                  (event.key === "ArrowRight" ? 1 : -1) +
                  buttons.length) %
                buttons.length;
        event.preventDefault();
        buttons[next].focus();
      }}
    />
  );
}

export function ModelViewerToolbarGroup({
  className,
  ...props
}: ComponentProps<"div">) {
  return (
    <div
      data-slot="model-viewer-toolbar-group"
      role="group"
      className={cn(
        "viewer-toolbar-group rounded-lg border bg-popover p-1 text-popover-foreground",
        className,
      )}
      {...props}
    />
  );
}

export type ModelViewerToolbarButtonProps = ComponentProps<typeof Button> & {
  label: string;
  active?: boolean;
  icon?: ReactNode;
};

export function ModelViewerToolbarButton({
  label,
  active,
  icon,
  children,
  ...props
}: ModelViewerToolbarButtonProps) {
  return (
    <Button
      data-slot="model-viewer-toolbar-button"
      data-state={active === undefined ? undefined : active ? "on" : "off"}
      size="icon-sm"
      variant={active ? "secondary" : "ghost"}
      aria-label={label}
      aria-pressed={active}
      tooltip={label}
      {...props}
    >
      {children ?? icon}
    </Button>
  );
}

export type ModelViewerControlsProps = Omit<
  ComponentProps<"div">,
  "onReset"
> & {
  mode: ViewerMode;
  onModeChange: (mode: ViewerMode) => void;
  shading: ViewerShading;
  onShadingChange: (shading: ViewerShading) => void;
  lighting: ViewerLighting;
  onLightingChange: (lighting: ViewerLighting) => void;
  grid: boolean;
  onGridChange: (visible: boolean) => void;
  floor?: boolean;
  onFloorChange?: (visible: boolean) => void;
  autoRotate?: boolean;
  onAutoRotateChange?: (rotating: boolean) => void;
  projection: "perspective" | "orthographic";
  onProjectionChange: (projection: "perspective" | "orthographic") => void;
  viewCube: ViewerViewCube | false;
  onViewCubeChange: (viewCube: ViewerViewCube | false) => void;
  inspectorOpen: boolean;
  onInspectorChange: (open: boolean) => void;
  onReset: () => void;
  captureDisabled?: boolean;
  onCapture: (action: "copy" | "download") => void;
};

/** The default controls, also usable outside ModelViewer with controlled state. */
export function ModelViewerControls({
  mode,
  onModeChange,
  shading,
  onShadingChange,
  lighting,
  onLightingChange,
  grid,
  onGridChange,
  floor = false,
  onFloorChange,
  autoRotate = false,
  onAutoRotateChange,
  projection,
  onProjectionChange,
  viewCube,
  onViewCubeChange,
  inspectorOpen,
  onInspectorChange,
  onReset,
  captureDisabled,
  onCapture,
  ...props
}: ModelViewerControlsProps) {
  const [captureMenuOpen, setCaptureMenuOpen] = useState(false);
  return (
    <ModelViewerToolbar {...props}>
      <ModelViewerToolbarGroup aria-label="Shading">
        <DropdownMenu modal={false}>
          <DropdownMenuTrigger
            render={
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="viewer-shading-trigger"
                aria-label={`Shading: ${shading}`}
              >
                {shadingLabels[shading]}
                <ChevronDown />
              </Button>
            }
          />
          <DropdownMenuContent
            align="start"
            sideOffset={6}
            className="min-w-40"
          >
            <DropdownMenuRadioGroup
              aria-label="Shading"
              value={shading}
              onValueChange={onShadingChange}
            >
              {(["realistic", "solid", "normals", "wireframe"] as const).map(
                (option) => (
                  <DropdownMenuRadioItem
                    key={option}
                    value={option}
                    closeOnClick
                  >
                    {shadingLabels[option]}
                  </DropdownMenuRadioItem>
                ),
              )}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>
      </ModelViewerToolbarGroup>
      <ModelViewerToolbarGroup aria-label="Interaction mode">
        <ModelViewerToolbarButton
          icon={<Rotate3D />}
          label="Orbit camera"
          active={mode === "orbit"}
          onClick={() => onModeChange("orbit")}
        />
        <ModelViewerToolbarButton
          icon={<LayoutGrid />}
          label="Four-view split"
          active={mode === "split"}
          onClick={() => onModeChange("split")}
        />
        <ModelViewerToolbarButton
          icon={<Footprints />}
          label="Fly camera"
          active={mode === "firstPerson"}
          onClick={() => onModeChange("firstPerson")}
        />
        {onAutoRotateChange && (
          <ModelViewerToolbarButton
            icon={<RotateCw />}
            label="Rotate automatically"
            active={autoRotate}
            disabled={mode !== "orbit"}
            onClick={() => onAutoRotateChange(!autoRotate)}
          />
        )}
      </ModelViewerToolbarGroup>
      <ModelViewerToolbarGroup aria-label="Scene options">
        <DropdownMenu modal={false}>
          <DropdownMenuTrigger
            render={
              <Button type="button" size="icon-sm" variant="ghost" aria-label={`Lighting: ${lighting}`} tooltip="Lighting">
                <CloudSun />
              </Button>
            }
          />
          <DropdownMenuContent className="min-w-40">
            <DropdownMenuRadioGroup aria-label="Lighting" value={lighting} onValueChange={onLightingChange}>
              {(["day", "night", "outside"] as const).map((value) => (
                <DropdownMenuRadioItem key={value} value={value} closeOnClick>
                  {value === "outside" ? "Outside sky" : value === "day" ? "Day studio" : "Night studio"}
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>
        <ModelViewerToolbarButton
          icon={<Grid2X2 />}
          label="Show grid"
          active={grid}
          onClick={() => onGridChange(!grid)}
        />
        {onFloorChange && (
          <ModelViewerToolbarButton
            icon={<Layers3 />}
            label="Show floor"
            active={floor}
            onClick={() => onFloorChange(!floor)}
          />
        )}
        <ModelViewerToolbarButton
          icon={<ScanSearch />}
          label="Orthographic view"
          active={projection === "orthographic"}
          onClick={() =>
            onProjectionChange(
              projection === "orthographic" ? "perspective" : "orthographic",
            )
          }
        />
        <DropdownMenu modal={false}>
          <DropdownMenuTrigger
            render={
              <Button
                type="button"
                size="icon-sm"
                variant="ghost"
                aria-label="View cube options"
              >
                <Box />
              </Button>
            }
          />
          <DropdownMenuContent className="min-w-40">
            <DropdownMenuRadioGroup
              aria-label="View cube"
              value={viewCube}
              onValueChange={onViewCubeChange}
            >
              {([false, "drei", "asset-studio"] as const).map((value) => (
                <DropdownMenuRadioItem
                  key={String(value)}
                  value={value}
                  closeOnClick
                >
                  {value === false
                    ? "Off"
                    : value === "drei"
                      ? "Drei cube"
                      : "Asset Studio"}
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>
        <ModelViewerToolbarButton
          icon={<ListTree />}
          label="Inspect model"
          active={inspectorOpen}
          onClick={() => onInspectorChange(!inspectorOpen)}
        />
        <ModelViewerToolbarButton
          icon={<RotateCcw />}
          label="Reset view"
          onClick={onReset}
        />
        <DropdownMenu modal={false} open={captureMenuOpen} onOpenChange={setCaptureMenuOpen}>
          <DropdownMenuTrigger
            render={
              <Button
                type="button"
                size="icon-sm"
                variant={captureMenuOpen ? "secondary" : "ghost"}
                aria-label="Screenshot options"
                title="Screenshot options"
                disabled={captureDisabled}
              >
                <Camera />
              </Button>
            }
          />
          <DropdownMenuContent align="end" sideOffset={8} className="min-w-52">
            <div className="flex items-center justify-between border-b px-2 py-1.5 text-xs font-medium">
              Capture view <span className="text-muted-foreground">PNG</span>
            </div>
            <DropdownMenuItem onClick={() => void onCapture("copy")}>
              <Copy /> Copy to clipboard
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => void onCapture("download")}>
              <Download /> Download image
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </ModelViewerToolbarGroup>
    </ModelViewerToolbar>
  );
}

const animationSpeeds = [0.5, 1, 1.5, 2];

export type ModelViewerAnimationControlsProps = ComponentProps<"div"> & {
  clips: string[];
  animation: string | null;
  onAnimationChange: (clip: string) => void;
  playing: boolean;
  onPlayingChange: (playing: boolean) => void;
  speed: number;
  onSpeedChange: (speed: number) => void;
  onRestart: () => void;
};

export function ModelViewerAnimationControls({
  clips,
  animation,
  onAnimationChange,
  playing,
  onPlayingChange,
  speed,
  onSpeedChange,
  onRestart,
  className,
  ...props
}: ModelViewerAnimationControlsProps) {
  return (
    <ModelViewerToolbar
      placement="animation"
      data-slot="model-viewer-animation-controls"
      aria-label="Animation controls"
      className={cn(
        "rounded-lg border bg-popover p-1 text-popover-foreground",
        className,
      )}
      {...props}
    >
      <ModelViewerToolbarButton
        icon={playing ? <Pause /> : <Play />}
        label={playing ? "Pause animation" : "Play animation"}
        active={playing}
        onClick={() => onPlayingChange(!playing)}
      />
      <DropdownMenu modal={false}>
        <DropdownMenuTrigger
          render={
            <Button
              type="button"
              size="sm"
              variant="ghost"
              className="viewer-animation-name"
            >
              <span className="truncate">{animation ?? "No animation"}</span>
              <ChevronDown />
            </Button>
          }
        />
        <DropdownMenuContent align="start" sideOffset={6} className="min-w-52">
          <DropdownMenuRadioGroup
            aria-label="Animation clip"
            value={animation}
            onValueChange={onAnimationChange}
          >
            {clips.map((name) => (
              <DropdownMenuRadioItem key={name} value={name} closeOnClick>
                {name}
              </DropdownMenuRadioItem>
            ))}
          </DropdownMenuRadioGroup>
        </DropdownMenuContent>
      </DropdownMenu>
      <ModelViewerToolbarButton
        icon={<RotateCcw />}
        label="Restart animation"
        onClick={onRestart}
      />
      <Button
        type="button"
        size="sm"
        variant="ghost"
        aria-label={`Animation speed ${speed}×`}
        title={`Animation speed ${speed}×`}
        onClick={() =>
          onSpeedChange(
            animationSpeeds[
              (animationSpeeds.indexOf(speed) + 1) % animationSpeeds.length
            ] ?? 1,
          )
        }
      >
        <Gauge />
        <span className="tabular-nums">{speed}×</span>
      </Button>
    </ModelViewerToolbar>
  );
}

"use client";

import {
  Box,
  ChevronDown,
  ChevronRight,
  Crosshair,
  Image,
  Layers,
  Search,
  Triangle,
  X,
} from "lucide-react";
import { useId, useMemo, useState, type ComponentProps } from "react";
import { cn } from "@/lib/utils";
import { indexHierarchy } from "./inspector-hierarchy";
import type { ModelInspection } from "./model-inspection";
import type { ModelInspectorPosition } from "./model-viewer-types";
import {
  ViewerControlButton as Button,
  ViewerUiProvider,
  type ViewerUiComponents,
} from "./viewer-ui";
import "./model-viewer.css";

export type ModelInspectorProps = ComponentProps<"aside"> & {
  inspection: ModelInspection;
  selectedMesh?: string | null;
  onSelectMesh: (id: string | null) => void;
  onClose?: () => void;
  /** Side of the viewer used by the positioned inspector. Defaults to right. */
  position?: ModelInspectorPosition;
  className?: string;
  components?: Partial<ViewerUiComponents>;
};

export function ModelInspector({
  inspection,
  selectedMesh,
  onSelectMesh,
  onClose,
  position = "right",
  className,
  components,
  ...props
}: ModelInspectorProps) {
  const [query, setQuery] = useState("");
  const [collapsed, setCollapsed] = useState<Set<string>>(() => new Set());
  const heading = useId();
  const selected = inspection.nodes.find((node) => node.id === selectedMesh);
  const hierarchy = useMemo(() => indexHierarchy(inspection.nodes), [inspection.nodes]);
  const visible = useMemo(() => hierarchy.visible(query, collapsed), [hierarchy, query, collapsed]);
  const [page, setPage] = useState({ nodes: inspection.nodes, query, limit: 200 });
  const limit = page.nodes === inspection.nodes && page.query === query ? page.limit : 200;
  function changeQuery(next: string) {
    setQuery(next);
    setPage({ nodes: inspection.nodes, query: next, limit: 200 });
  }
  function toggle(id: string) {
    setCollapsed((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  return (
    <ViewerUiProvider components={components}>
      <aside
        data-slot="model-inspector"
        data-position={position}
        className={cn("viewer-inspector", className)}
        aria-labelledby={heading}
        {...props}
      >
        <header className="inspector-header">
          <span className="inspector-emblem">
            <Box size={18} />
          </span>
          <div>
            <span className="inspector-eyebrow">Scene overview</span>
            <h3 id={heading}>Model inspector</h3>
          </div>
          {onClose && (
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label="Close inspector"
              onClick={onClose}
            >
              <X size={16} />
            </Button>
          )}
        </header>
        <div className="inspector-metrics">
          {[
            { label: "Triangles", value: inspection.triangles, Icon: Triangle },
            { label: "Materials", value: inspection.materials, Icon: Layers },
            { label: "Textures", value: inspection.textures, Icon: Image },
          ].map(({ label, value, Icon }) => (
            <div key={label}>
              <Icon size={14} />
              <strong>{value.toLocaleString()}</strong>
              <span>{label}</span>
            </div>
          ))}
        </div>
        <section className="inspector-dimensions" aria-label="Dimensions">
          <div className="inspector-section-label">
            Dimensions <span>model units</span>
          </div>
          <div className="inspector-axis-values">
            {inspection.dimensions.map((value, index) => (
              <div key={index}>
                <span data-axis={index}>{["X", "Y", "Z"][index]}</span>
                <strong>{Number(value.toPrecision(4))}</strong>
              </div>
            ))}
          </div>
        </section>
        <div className="inspector-hierarchy-heading">
          <span className="inspector-section-label">Hierarchy</span>
          <span>
            {inspection.nodes.filter((node) => node.mesh).length} meshes
          </span>
        </div>
        <label className="inspector-search">
          <Search size={14} />
          <input
            aria-label="Search hierarchy"
            placeholder="Find an object…"
            value={query}
            onChange={(event) => changeQuery(event.target.value)}
          />
          {query && (
            <Button
              size="icon-sm"
              variant="ghost"
              aria-label="Clear search"
              onClick={() => changeQuery("")}
            >
              <X size={12} />
            </Button>
          )}
        </label>
        <ul className="inspector-tree" aria-label="Scene hierarchy">
          {visible.slice(0, limit).map((node) => {
            const hasChildren = hierarchy.branches.has(node.id);
            return (
              <li
                data-slot="model-inspector-node"
                data-state={selectedMesh === node.id ? "selected" : undefined}
                key={node.id}
                style={{ paddingLeft: Math.min(node.depth, 8) * 12 }}
                className={cn(selectedMesh === node.id && "is-selected")}
              >
                {hasChildren ? (
                  <Button
                    size="icon-sm"
                    variant="ghost"
                    aria-label={`${collapsed.has(node.id) ? "Expand" : "Collapse"} ${node.name}`}
                    aria-expanded={!collapsed.has(node.id)}
                    onClick={() => toggle(node.id)}
                  >
                    {collapsed.has(node.id) ? (
                      <ChevronRight size={12} />
                    ) : (
                      <ChevronDown size={12} />
                    )}
                  </Button>
                ) : (
                  <span className="inspector-spacer" />
                )}
                <Button
                  variant="ghost"
                  size="sm"
                  className="inspector-node min-w-0 flex-1 justify-start"
                  disabled={!node.mesh}
                  aria-pressed={
                    node.mesh ? selectedMesh === node.id : undefined
                  }
                  onClick={() => onSelectMesh(node.id)}
                >
                  {node.mesh ? <Box size={13} /> : <Layers size={13} />}
                  <span>{node.name}</span>
                  <small className="ml-auto rounded-sm bg-muted px-1 text-xs text-muted-foreground">
                    {node.mesh ? "Mesh" : node.type}
                  </small>
                </Button>
              </li>
            );
          })}
        </ul>
        {visible.length > limit && (
          <Button variant="outline" size="sm" onClick={() => setPage({ nodes: inspection.nodes, query, limit: limit + 200 })}>
            Show {Math.min(200, visible.length - limit)} more objects
          </Button>
        )}
        {visible.length === 0 && (
          <div className="inspector-empty">No objects match “{query}”.</div>
        )}
        <footer className="inspector-selection">
          <Crosshair size={15} />
          <div>
            <span>{selected ? "Selected object" : "Nothing selected"}</span>
            <strong>{selected?.name ?? "Choose a mesh to inspect"}</strong>
          </div>
          {selected && (
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label="Clear selection"
              onClick={() => onSelectMesh(null)}
            >
              <X size={14} />
            </Button>
          )}
        </footer>
      </aside>
    </ViewerUiProvider>
  );
}

"use client";

import {
  createContext,
  useContext,
  useMemo,
  type ComponentProps,
  type ComponentType,
  type ReactElement,
  type ReactNode,
} from "react";
import { Button as ShadcnButton } from "@/components/ui/button";
import {
  Tooltip,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

import { TooltipContent } from "./viewer-popups";

export type ViewerTooltipProps = { children: ReactElement; content: ReactNode };
export type ViewerUiComponents = {
  /** Forward the ref, event handlers, aria attributes, and className to the underlying button. */
  Button: ComponentType<ComponentProps<typeof ShadcnButton>>;
  /** Render children as the trigger, preserving its ref and event handlers. */
  Tooltip: ComponentType<ViewerTooltipProps>;
};

function DefaultTooltip({ children, content }: ViewerTooltipProps) {
  const hasProvider = useContext(ViewerUiContext) !== null;
  const tooltip = (
    <Tooltip>
      <TooltipTrigger render={children} />
      <TooltipContent>{content}</TooltipContent>
    </Tooltip>
  );
  return hasProvider ? (
    tooltip
  ) : (
    <TooltipProvider delay={350}>{tooltip}</TooltipProvider>
  );
}

const defaultComponents: ViewerUiComponents = {
  Button: ShadcnButton,
  Tooltip: DefaultTooltip,
};
const ViewerUiContext = createContext<ViewerUiComponents | null>(null);

export function ViewerUiProvider({
  components,
  children,
}: {
  components?: Partial<ViewerUiComponents>;
  children: ReactNode;
}) {
  const inherited = useContext(ViewerUiContext) ?? defaultComponents;
  const value = useMemo(
    () => ({ ...inherited, ...components }),
    [inherited, components],
  );
  return (
    <ViewerUiContext.Provider value={value}>
      <TooltipProvider delay={350}>{children}</TooltipProvider>
    </ViewerUiContext.Provider>
  );
}

export type ViewerControlButtonProps = ComponentProps<typeof ShadcnButton> & {
  /** Override the accessible-label tooltip, or use false to disable it. */
  tooltip?: ReactNode | false;
};

export function ViewerControlButton({
  title,
  tooltip,
  type = "button",
  ...props
}: ViewerControlButtonProps) {
  const { Button, Tooltip: TooltipImpl } =
    useContext(ViewerUiContext) ?? defaultComponents;
  const label =
    tooltip === undefined ? (title ?? props["aria-label"]) : tooltip;
  const button = <Button type={type} {...props} />;
  return label ? <TooltipImpl content={label}>{button}</TooltipImpl> : button;
}

