import { createContext, useContext, useSyncExternalStore } from "react";
import type { ModelViewerState } from "./model-viewer-types";
import type { useModelViewerRuntime } from "./use-model-viewer-runtime";

/** Internal renderer context. Not part of the public barrel. */
export const ModelViewerContext = createContext<ReturnType<
  typeof useModelViewerRuntime
> | null>(null);

export function useOptionalViewerRuntime() {
  return useContext(ModelViewerContext);
}

export function useViewerRuntime() {
  const context = useOptionalViewerRuntime();
  if (!context)
    throw new Error(
      "Model viewer parts must be used inside <ModelViewerRoot> or <ModelViewer>.",
    );
  return context;
}

/** State and actions scoped to the nearest viewer. */
export function useModelViewer(): ModelViewerState {
  return useViewerRuntime().state;
}

/** Live primary orbit camera view without rerendering the whole viewer. */
export function useModelViewerCamera() {
  const { cameraStore } = useViewerRuntime();
  return useSyncExternalStore(cameraStore.subscribe, cameraStore.getSnapshot, () => null);
}

import type { ViewerCameraOptions, ViewerCameraState } from "./model-viewer-types";

/** Mutable camera data lives outside React's root render loop. */
export function createViewerCameraStore() {
  let snapshot: ViewerCameraState | null = null;
  let controller: ((view: ViewerCameraState, transition: boolean) => void) | null = null;
  const listeners = new Set<() => void>();
  const getSnapshot = () => snapshot;
  const subscribe = (listener: () => void) => {
    listeners.add(listener);
    return () => { listeners.delete(listener); };
  };
  const publish = (view: ViewerCameraState | null) => {
    const current = snapshot;
    if (view && current &&
      view.position.every((n, i) => Math.abs(n - current.position[i]) < 1e-6) &&
      view.target.every((n, i) => Math.abs(n - current.target[i]) < 1e-6)) return;
    if (!view && !snapshot) return;
    snapshot = view;
    listeners.forEach((listener) => listener());
  };
  const register = (next: typeof controller) => {
    controller = next;
    if (!next) publish(null);
  };
  const setView = (view: ViewerCameraState, options?: ViewerCameraOptions) => {
    if (!controller || !validCameraView(view)) return false;
    controller(view, options?.transition ?? true);
    return true;
  };
  return { getSnapshot, subscribe, publish, register, setView };
}

export type ViewerCameraStore = ReturnType<typeof createViewerCameraStore>;

function validCameraView(view: ViewerCameraState) {
  const values = [...view.position, ...view.target];
  return values.every(Number.isFinite) &&
    view.position.some((n, i) => Math.abs(n - view.target[i]) > 1e-9);
}

import type { ViewerLighting } from "./model-viewer-types";

export function viewerBackgroundColor(lighting: ViewerLighting) {
  if (lighting === "night") return "#17243a";
  if (lighting === "outside") return "#dbe9ee";
  return "#f5f5f5";
}

import { BackSide } from "three";

const vertexShader = `
  varying vec3 vDirection;
  void main() {
    vDirection = normalize(position);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    gl_Position.z = gl_Position.w;
  }
`;

const fragmentShader = `
  varying vec3 vDirection;
  void main() {
    float elevation = clamp(vDirection.y, 0.0, 1.0);
    vec3 horizon = vec3(0.859, 0.914, 0.933);
    vec3 zenith = vec3(0.31, 0.58, 0.84);
    vec3 color = mix(horizon, zenith, pow(elevation, 0.7));
    vec3 sun = normalize(vec3(0.65, 0.6, -0.25));
    float halo = pow(max(dot(normalize(vDirection), sun), 0.0), 64.0);
    color = mix(color, vec3(1.0, 0.95, 0.78), halo * 0.4);
    gl_FragColor = vec4(color, 1.0);
  }
`;

/** Self-contained daylight sky: no remote HDRI or asset request. */
export function OutsideSky() {
  return (
    <mesh scale={900} frustumCulled={false} renderOrder={-1000}>
      <sphereGeometry args={[1, 32, 16]} />
      <shaderMaterial
        side={BackSide}
        depthWrite={false}
        depthTest={false}
        vertexShader={vertexShader}
        fragmentShader={fragmentShader}
      />
    </mesh>
  );
}

export type ViewerLifecycle = {
  status: "idle" | "loading" | "ready" | "error";
  readyPanes: ReadonlySet<number>;
  generation: number;
};

export type ViewerLifecycleEvent =
  | { type: "mount" }
  | { type: "reset" }
  | { type: "unmount" }
  | { type: "ready"; pane: number; expectedPanes: number }
  | { type: "error" };

export const initialViewerLifecycle: ViewerLifecycle = {
  status: "idle",
  readyPanes: new Set(),
  generation: 0,
};

export function viewerLifecycleReducer(
  current: ViewerLifecycle,
  event: ViewerLifecycleEvent,
): ViewerLifecycle {
  switch (event.type) {
    case "mount":
      return { status: "loading", readyPanes: new Set(), generation: current.generation + 1 };
    case "reset":
      return {
        status: current.status === "idle" ? "idle" : "loading",
        readyPanes: new Set(),
        generation: current.generation + 1,
      };
    case "unmount":
      return { status: "idle", readyPanes: new Set(), generation: current.generation + 1 };
    case "error":
      return current.status === "loading" || current.status === "ready"
        ? { ...current, status: "error" }
        : current;
    case "ready": {
      if (current.status !== "loading" || current.readyPanes.has(event.pane)) return current;
      const readyPanes = new Set(current.readyPanes).add(event.pane);
      return {
        ...current,
        readyPanes,
        status: readyPanes.size >= event.expectedPanes ? "ready" : "loading",
      };
    }
  }
}

