  enableCapture = showUi,
  showOrientation = showUi,
  viewCube: controlledViewCube,
  defaultViewCube = "asset-studio",
  viewCubePosition = "top-right",
  viewCubeMargin,
  onViewCubeChange,
  projection: controlledProjection,
  defaultProjection = "perspective",
  onProjectionChange,
  showInspector,
  inspectorOpen: controlledInspectorOpen,
  defaultInspectorOpen = false,
  onInspectorOpenChange,
  onInspect,
  autoRotate: controlledAutoRotate,
  defaultAutoRotate = false,
  onAutoRotateChange,
  autoRotateSpeed = 0.15,
  cameraPreset: controlledCameraPreset,
  defaultCameraPreset = "isometric",
  onCameraPresetChange,
  onCameraChange,
  animation: controlledAnimation,
  defaultAnimation = null,
  onAnimationChange,
  animationPlaying: controlledAnimationPlaying,
  defaultAnimationPlaying = false,
  onAnimationPlayingChange,
  animationSpeed: controlledAnimationSpeed,
  defaultAnimationSpeed = 1,
  onAnimationSpeedChange,
  loopAnimation = true,
  environment = true,
  poster,
  showFileName = false,
  loadingFallback,
  errorFallback,
  showRetry = false,
  pauseWhenHidden = true,
  useDraco = true,
  useMeshopt = true,
  extendLoader,
  clearCacheOnUnmount = src?.startsWith("blob:") ?? false,
  respectReducedMotion = true,
  onPerformanceChange,
  onLoad,
  onError,
  ...props
}: ModelViewerRootProps) {
  const [mode, setMode] = useControlledState(
    controlledMode,
    defaultMode,
    onModeChange,
  );
  const [viewCube, setViewCube] = useControlledState(
    controlledViewCube,
    defaultViewCube,
    onViewCubeChange,
  );
  const [projection, setProjection] = useControlledState(
    controlledProjection,
    defaultProjection,
    onProjectionChange,
  );
  const [inspectorOpen, setInspectorOpen] = useControlledState(
    controlledInspectorOpen,
    showInspector ?? defaultInspectorOpen,
    onInspectorOpenChange,
  );
  const [inspection, setInspection] = useState<ModelInspection | null>(null);
  const [selectedMesh, setSelectedMesh] = useState<string | null>(null);
  const [quality, setQuality] = useState(1.5);
  const [lighting, setLighting] = useControlledState(
    controlledLighting,
    defaultLighting,
    onLightingChange,
  );
  const [shading, setShading] = useControlledState(
    controlledShading,
    defaultShading,
    onShadingChange,
  );
  const [grid, setGrid] = useControlledState(
    controlledGrid,
    defaultShowGrid,
    onGridChange,
  );
  const [floor, setFloor] = useControlledState(
    controlledFloor,
    defaultShowFloor,
    onFloorChange,
  );
  const [autoRotate, setAutoRotate] = useControlledState(
    controlledAutoRotate,
    defaultAutoRotate,
    onAutoRotateChange,
  );
  const [cameraPreset, setCameraPreset] = useControlledState(
    controlledCameraPreset,
    defaultCameraPreset,
    onCameraPresetChange,
  );
  const [animation, setAnimation, resetAnimation] = useControlledState<string | null>(
    controlledAnimation,
    defaultAnimation,
    onAnimationChange,
  );
  const [animationPlaying, setAnimationPlaying] = useControlledState(
    controlledAnimationPlaying,
    defaultAnimationPlaying,
    onAnimationPlayingChange,
  );
  const [animationSpeed, setAnimationSpeed] = useControlledState(
    controlledAnimationSpeed,
    defaultAnimationSpeed,
    onAnimationSpeedChange,
  );
  const [animationNames, setAnimationNames] = useState<string[]>([]);
  const [cameraStore] = useState(createViewerCameraStore);
  const [lifecycle, dispatchLifecycle] = useReducer(viewerLifecycleReducer, initialViewerLifecycle);
  const loaded = lifecycle.status === "ready" || lifecycle.status === "error";
  const viewerError = lifecycle.status === "error";
  const [retryToken, setRetryToken] = useState(0);
  const { feedback, report, clearFeedback } = useViewerFeedback();
  const [locked, setLocked] = useState(false);
  const [pointerLockAvailable, setPointerLockAvailable] = useState(true);
  const [resetToken, setResetToken] = useState(0);
  const [animationResetToken, setAnimationResetToken] = useState(0);
  const reducedMotion = useReducedMotion(respectReducedMotion);
  const viewerRef = useRef<HTMLDivElement | null>(null);
  const viewerHidden = useViewerHidden(viewerRef);
  const renderingPaused = pauseWhenHidden && viewerHidden;
  useImperativeHandle(ref, () => viewerRef.current!, []);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [captureReady, setCaptureReady] = useState(false);
  const loadReportedGeneration = useRef<number | null>(null);
  const viewerKey = useId();
  const cubes = requestedCubes ?? !src;
  const expectedPanes = mode === "split" ? splitPanes.length : 1;
  const [sceneMounted, setSceneMountedState] = useState(false);
  /** Clear everything derived from the current scene/load generation. */
  const resetModelSession = useCallback(() => {
    setAnimationNames([]);
    setInspection(null);
    setSelectedMesh(null);
    setLocked(false);
  }, []);
  const setSceneMounted = useCallback((mounted: boolean) => {
    setSceneMountedState(mounted);
    dispatchLifecycle({ type: mounted ? "mount" : "unmount" });
    if (!mounted) {
      // The canvas goes away with the scene, so capture must wait for the next one.
      setCaptureReady(false);
      resetModelSession();
    }
  }, [resetModelSession]);
  const [toolbarOffset, setToolbarOffset] = useState(0);
  const toolbarMeasurements = useRef(new Map<HTMLElement, number>());
  const reportToolbar = useCallback(
    (element: HTMLElement, offset: number | null) => {
      if (offset === null) toolbarMeasurements.current.delete(element);
      else toolbarMeasurements.current.set(element, offset);
      setToolbarOffset(Math.max(0, ...toolbarMeasurements.current.values()));
    },
    [],
  );
  const effectiveAutoRotate =
    autoRotate && !reducedMotion && !renderingPaused && mode === "orbit";
  const effectiveAnimationPlaying =
    animationPlaying && !reducedMotion && !renderingPaused;
  const paneTracks = useRef(
    Array.from({ length: splitPanes.length }, () => ({
      current: null as HTMLDivElement | null,
    })),
  ).current;

  useEffect(() => {
    dispatchLifecycle({ type: "reset" });
    clearFeedback();
    resetModelSession();
  }, [src, mode, enableCapture, clearFeedback, resetModelSession]);

  useEffect(() => () => {
    if (src && clearCacheOnUnmount) useGLTF.clear(src);
  }, [src, clearCacheOnUnmount]);

  useEffect(() => {
    if (lifecycle.status === "ready" && loadReportedGeneration.current !== lifecycle.generation) {
      loadReportedGeneration.current = lifecycle.generation;
      onLoad?.();
    }
  }, [lifecycle.status, lifecycle.generation, onLoad]);

  const effectiveAnimation =
    controlledAnimation === null
      ? null
      : animationNames.includes(animation ?? "")
        ? animation
        : controlledAnimation === undefined
          ? (animationNames[0] ?? null)
          : animation;
  const previousAnimationSrc = useRef(src);
  useEffect(() => {
    if (previousAnimationSrc.current === src) return;
    previousAnimationSrc.current = src;
    if (controlledAnimation === undefined) resetAnimation(defaultAnimation);
  }, [src, defaultAnimation, controlledAnimation, resetAnimation]);

  useEffect(() => {
    if (showInspector !== undefined && controlledInspectorOpen === undefined)
      setInspectorOpen(showInspector);
  }, [showInspector, controlledInspectorOpen, setInspectorOpen]);
  useEffect(() => {
    const rejectLock = () => {
      setPointerLockAvailable(false);
      setLocked(false);
    };
    document.addEventListener("pointerlockerror", rejectLock);
    return () => document.removeEventListener("pointerlockerror", rejectLock);
  }, []);
  const reportInspection = useCallback(
    (value: ModelInspection) => {
      setInspection(value);
      onInspect?.(value);
    },
    [onInspect],
  );

  const { fullscreen, isExpanded, toggleFullscreen } = useViewerFullscreen(viewerRef, report);

  useEffect(() => {
    setPointerLockAvailable("requestPointerLock" in HTMLElement.prototype);
  }, []);

  const markReady = useCallback((index: number) => {
    dispatchLifecycle({ type: "ready", pane: index, expectedPanes });
  }, [expectedPanes]);

  const reportAnimations = useCallback((names: string[]) => {
    setAnimationNames((current) =>
      current.length === names.length &&
      current.every((name, index) => name === names[index])
        ? current
        : names,
    );
  }, []);

  const fail = useCallback(
    (error: Error) => {
      dispatchLifecycle({ type: "error" });
      onError?.(error);
    },
    [onError],
  );

  const retry = useCallback(() => {
    if (!viewerError || !src) return;
    useGLTF.clear(src);
    dispatchLifecycle({ type: "reset" });
    clearFeedback();
    resetModelSession();
    setRetryToken((value) => value + 1);
  }, [src, viewerError, clearFeedback, resetModelSession]);

  function changeMode(next: ViewerMode) {
    if (next === mode) return;
    if (document.pointerLockElement) document.exitPointerLock();
    setMode(next);
  }

  const canCapture = enableCapture && captureReady && sceneMounted && loaded && !viewerError;
  const capture = useViewerCapture({
    canvasRef,
    canCapture,
    lighting,
    fileName: ariaLabel ?? alt,
    report,
  });

  const status = lifecycle.status;
  const state: ModelViewerState = {
    mode,
    setMode: changeMode,
    lighting,
    setLighting,
    shading,
    setShading,
    showGrid: grid,
    setShowGrid: setGrid,
    showFloor: floor,
    setShowFloor: setFloor,
    autoRotate,
    setAutoRotate,
    projection,
    setProjection,
    viewCube,
    setViewCube,
    cameraPreset,
    setCameraPreset,
    resetView: () => setResetToken((value) => value + 1),
    getCameraView: cameraStore.getSnapshot,
    setCameraView: cameraStore.setView,
    inspectorOpen,
    setInspectorOpen,
    inspection,
    selectedMesh,
    setSelectedMesh,
    animation: effectiveAnimation,
    animationNames,
    setAnimation,
    animationPlaying,
    setAnimationPlaying,
    animationSpeed,
    setAnimationSpeed,
    restartAnimation: () => setAnimationResetToken((value) => value + 1),
    reducedMotion,
    renderingPaused,
    retry,
    status,
    canCapture,
    capture,
    fullscreen,
    toggleFullscreen,
    feedback,
  };
  return {
    state,
    root: { components, className, style, children, height, props, isExpanded },
    viewerRef,
    canvasRef,
    enableCapture,
    setCaptureReady,
    viewerKey,
    cameraStore,
    toolbarOffset,
    reportToolbar,
    setSceneMounted,
    // Renderer configuration stays private; useModelViewer exposes only state/actions.
    src,
    accessibleLabel: ariaLabelledBy ? undefined : (ariaLabel ?? alt),
    ariaLabelledBy,
    mode,
    lighting,
    shading,
    grid,
    floor,
    floorColor,
    cubes,
    cameraPreset,
    resetToken,
    showUi,
    showOrientation,
    viewCube,
    viewCubePosition,
    viewCubeMargin,
    projection,
    effectiveAutoRotate,
    autoRotateSpeed,
    effectiveAnimation,
    effectiveAnimationPlaying,
    animationSpeed,
    animationResetToken,
    loopAnimation,
    environment,
    poster,
    showFileName,
    loadingFallback,
    errorFallback,
    showRetry,
    retryToken,
    retry,
    renderingPaused,
    useDraco,
    useMeshopt,
    extendLoader,
    loaded,
    status,
    quality,
    setQuality,
    onPerformanceChange,
    onCameraChange,
    selectedMesh,
    setSelectedMesh,
    reportInspection,
    pointerLockAvailable,
    locked,
    setLocked,
    paneTracks,
    markReady,
    reportAnimations,
    fail,
  };
}

"use client";

import { createPortal, useFrame, useThree, type ComputeFunction } from "@react-three/fiber";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useState,
  type RefObject,
  type ReactNode,
} from "react";
import { Scene } from "three";

export function ScissorView({
  track,
  index,
  clearColor,
  children,
}: {
  track: RefObject<HTMLDivElement | null>;
  index: number;
  clearColor: string;
  children: ReactNode;
}) {
  const [scene] = useState(() => new Scene());
  const [size, setSize] = useState({ width: 1, height: 1, top: 0, left: 0 });

  useLayoutEffect(() => {
    let frame = 0;
    let observer: ResizeObserver | undefined;
    const measure = () => {
      const element = track.current;
      if (!element) return;
      const rect = element.getBoundingClientRect();
      setSize((current) =>
        current.width === rect.width &&
        current.height === rect.height &&
        current.top === rect.top &&
        current.left === rect.left
          ? current
          : {
              width: rect.width,
              height: rect.height,
              top: rect.top,
              left: rect.left,
            },
      );
    };
    // Canvas and its DOM tracks commit in separate React roots. The R3F
    // layout effect can run before the DOM ref has been attached.
    const observeTrack = () => {
      const element = track.current;
      if (!element) {
        frame = requestAnimationFrame(observeTrack);
        return;
      }
      measure();
      observer = new ResizeObserver(measure);
      observer.observe(element);
    };
    observeTrack();
    window.addEventListener("scroll", measure, true);
    window.addEventListener("resize", measure);
    return () => {
      cancelAnimationFrame(frame);
      observer?.disconnect();
      window.removeEventListener("scroll", measure, true);
      window.removeEventListener("resize", measure);
    };
  }, [track]);

  const compute = useCallback<ComputeFunction>(
    (event, state) => {
      const rect = track.current?.getBoundingClientRect();
      if (!rect || rect.width === 0 || rect.height === 0) return;
      if (
        !(event.target instanceof Node) ||
        !track.current?.contains(event.target)
      ) {
        state.pointer.set(10000, 10000);
        state.raycaster.setFromCamera(state.pointer, state.camera);
        return;
      }
      state.pointer.set(
        ((event.clientX - rect.left) / rect.width) * 2 - 1,
        -((event.clientY - rect.top) / rect.height) * 2 + 1,
      );
      state.raycaster.setFromCamera(state.pointer, state.camera);
    },
    [track],
  );

  return createPortal(
    <ScissorRenderer
      track={track}
      size={size}
      index={index}
      clearColor={clearColor}
    >
      {children}
    </ScissorRenderer>,
    scene,
    { events: { compute, priority: index }, size },
  );
}

export function RedrawAfterResize() {
  const dpr = useThree((state) => state.viewport.dpr);
  const size = useThree((state) => state.size);
  const invalidate = useThree((state) => state.invalidate);
  useEffect(() => {
    // Changing pixel ratio clears WebGL's drawing buffer, even when the scene is idle.
    const frame = requestAnimationFrame(() => invalidate());
    return () => cancelAnimationFrame(frame);
  }, [dpr, size.width, size.height, invalidate]);
  return null;
}

function ScissorRenderer({
  track,
  size,
  index,
  clearColor,
  children,
}: {
  track: RefObject<HTMLDivElement | null>;
  size: { width: number; height: number; top: number; left: number };
  index: number;
  clearColor: string;
  children: ReactNode;
}) {
  const set = useThree((state) => state.set);
  useLayoutEffect(() => {
    // R3F portals refresh injected props when the parent store changes, not
    // necessarily when the track is measured. Keep this pane's size current
    // without depending on unrelated root renders or camera interactions.
    set({ size });
  }, [set, size]);

  useFrame((state) => {
    const element = track.current;
    if (!element) return;
    const rect = element.getBoundingClientRect();
    const canvasRect = state.gl.domElement.getBoundingClientRect();
    const visible =
      rect.width > 0 &&
      rect.height > 0 &&
      rect.right > canvasRect.left &&
      rect.left < canvasRect.right &&
      rect.bottom > canvasRect.top &&
      rect.top < canvasRect.bottom;
    if (!visible) return;

    if (index === 1) {
      state.gl.setScissorTest(false);
      state.gl.setClearColor(clearColor, 1);
      state.gl.clear(true, true, true);
    }

    const left = rect.left - canvasRect.left;
    const bottom = canvasRect.bottom - rect.bottom;
    const autoClear = state.gl.autoClear;
    state.gl.autoClear = false;
    state.gl.setViewport(left, bottom, rect.width, rect.height);
    state.gl.setScissor(left, bottom, rect.width, rect.height);
    state.gl.setScissorTest(true);
    state.gl.clear(false, true, true);
    state.gl.render(state.scene, state.camera);
    state.gl.setScissorTest(false);
    state.gl.autoClear = autoClear;
  }, index);
  return (
    <>
      {children}
      <group onPointerOver={() => undefined} />
    </>
  );
}

"use client";

import { Outlines, useGLTF } from "@react-three/drei";
import { createPortal, useFrame, useThree } from "@react-three/fiber";
import { retainModelResources } from "./model-resources";
import { useEffect, useMemo, useRef } from "react";
import {
  AnimationMixer,
  LoopOnce,
  LoopRepeat,
  MeshStandardMaterial,
  MeshBasicMaterial,
  MeshNormalMaterial,
  type Mesh,
  type Group,
} from "three";
import type { GLTFLoader } from "three-stdlib";
import { clone } from "three/addons/utils/SkeletonUtils.js";
import { inspectModel, prepareAnimationBounds, type ModelInspection } from "./model-inspection";
import type { ViewerShading } from "./model-viewer-types";

export function SceneObject({
  src,
  cubes,
  shading,
  animation,
  animationPlaying,
  animationSpeed,
  animationResetToken,
  loopAnimation,
  useDraco,
  useMeshopt,
  extendLoader,
  onReady,
  onAnimations,
  onInspect,
  selectedMesh,
  onSelectMesh,
}: {
  onInspect?: (value: ModelInspection) => void;
  selectedMesh: string | null;
  onSelectMesh: (id: string | null) => void;
  src?: string;
  cubes: boolean;
  shading: ViewerShading;
  animation: string | null;
  animationPlaying: boolean;
  animationSpeed: number;
  animationResetToken: number;
  loopAnimation: boolean;
  useDraco: boolean | string;
  useMeshopt: boolean;
  extendLoader?: (loader: GLTFLoader) => void;
  onReady: () => void;
  onAnimations: (names: string[]) => void;
}) {
  const group = useRef<Group>(null);
  useEffect(() => {
    if (group.current) onInspect?.(inspectModel(group.current));
  }, [src, cubes, onInspect]);
  useEffect(() => {
    if (!src) {
      onAnimations([]);
      onReady();
    }
  }, [src, onAnimations, onReady]);
  return (
    <group
      ref={group}
      onClick={(event) => {
        event.stopPropagation();
        onSelectMesh(event.object.userData.viewerNodeId ?? null);
      }}
    >
      {src && (
        <LoadedModel
          src={src}
          shading={shading}
          animation={animation}
          animationPlaying={animationPlaying}
          animationSpeed={animationSpeed}
          animationResetToken={animationResetToken}
          loopAnimation={loopAnimation}
          useDraco={useDraco}
          useMeshopt={useMeshopt}
          extendLoader={extendLoader}
          onReady={onReady}
          onAnimations={onAnimations}
          selectedMesh={selectedMesh}
          onSelectMesh={onSelectMesh}
        />
      )}
      {cubes && (
        <>
          <mesh
            name="Cube"
            castShadow
            position={[-1.25, 0.45, 0]}
            rotation={[0, 0.25, 0.08]}
          >
            <boxGeometry args={[0.9, 0.9, 0.9]} />
            <ViewerMaterial
              shading={shading}
              color="#b3c899"
            />
            {selectedMesh === "0/0" && <SelectionOutline />}
          </mesh>
          <mesh
            name="Dodecahedron"
            castShadow
            position={[1.05, 0.55, -0.55]}
            rotation={[0, -0.35, 0]}
          >
            <dodecahedronGeometry args={[0.55, 0]} />
            <ViewerMaterial
              shading={shading}
              color="#d19a78"
            />
            {selectedMesh === "0/1" && <SelectionOutline />}
          </mesh>
          <mesh name="Sphere" castShadow position={[0.15, 0.42, 1]}>
            <sphereGeometry args={[0.42, 48, 48]} />
            <ViewerMaterial
              shading={shading}
              color="#7fa7a7"
            />
            {selectedMesh === "0/2" && <SelectionOutline />}
          </mesh>
        </>
      )}
    </group>
  );
}

function LoadedModel({
  src,
  shading,
  animation,
  animationPlaying,
  animationSpeed,
  animationResetToken,
  loopAnimation,
  useDraco,
  useMeshopt,
  extendLoader,
  onReady,
  onAnimations,
  selectedMesh,
  onSelectMesh,
}: {
  selectedMesh: string | null;
  onSelectMesh: (id: string | null) => void;
  src: string;
  shading: ViewerShading;
  animation: string | null;
  animationPlaying: boolean;
  animationSpeed: number;
  animationResetToken: number;
  loopAnimation: boolean;
  useDraco: boolean | string;
  useMeshopt: boolean;
  extendLoader?: (loader: GLTFLoader) => void;
  onReady: () => void;
  onAnimations: (names: string[]) => void;
}) {
  const gltf = useGLTF(src, useDraco, useMeshopt, extendLoader);
  prepareAnimationBounds(gltf.scene, gltf.animations);
  const model = useMemo(() => {
    const result = clone(gltf.scene);
    result.traverse((object) => {
      if ((object as Mesh).isMesh) (object as Mesh).castShadow = true;
    });
    result.updateMatrixWorld(true);
    return result;
  }, [gltf.scene]);
  const selectedObject = useMemo(() => {
    if (!selectedMesh) return null;
    let match: Mesh | null = null;
    model.traverse((object) => {
      if ((object as Mesh).isMesh && object.userData.viewerNodeId === selectedMesh)
        match = object as Mesh;
    });
    return match;
  }, [model, selectedMesh]);
  useEffect(() => retainModelResources(model), [model]);
  const invalidate = useThree((state) => state.invalidate);
  const { mixer, actions, names } = useMemo(() => {
    const mixer = new AnimationMixer(model);
    return {
      mixer,
      names: gltf.animations.map(clip => clip.name),
      actions: Object.fromEntries(gltf.animations.map(clip => [clip.name, mixer.clipAction(clip)])),
    };
  }, [gltf.animations, model]);
  useEffect(() => () => {
    mixer.stopAllAction();
  }, [mixer]);
  const activeAction = animation ? actions[animation] : undefined;
  const advancing = useRef(false);
  useFrame((_, delta) => {
    // The first demand frame may include seconds spent idle. Do not apply that
    // elapsed time to a newly resumed or restarted action.
    mixer.update(advancing.current ? delta : 0);
    advancing.current = Boolean(activeAction?.isRunning() && activeAction.getEffectiveTimeScale() !== 0);
    if (advancing.current) invalidate();
  });
  const playback = useRef({ animationPlaying, animationSpeed });
  playback.current = { animationPlaying, animationSpeed };
  useEffect(() => {
    const restore: (() => void)[] = [];
    model.traverse((object) => {
      const mesh = object as Mesh;
      if (!mesh.isMesh) return;
      if (shading === "realistic") return;
      const original = mesh.material;
      const material = shading === "normals"
          ? new MeshNormalMaterial()
          : shading === "wireframe"
            ? new MeshBasicMaterial({ color: "#34483f", wireframe: true })
            : new MeshStandardMaterial({ color: "#a7aaa5", roughness: 0.82 });
      mesh.material = material;
      restore.push(() => {
        mesh.material = original;
        material.dispose();
      });
    });
    return () => restore.forEach((reset) => reset());
  }, [model, shading]);

  useEffect(() => {
    onAnimations(names);
    onReady();
  }, [gltf, names, onAnimations, onReady]);

  useEffect(() => {
    if (!activeAction) return;
    activeAction.reset();
    activeAction.clampWhenFinished = !loopAnimation;
    activeAction.setLoop(
      loopAnimation ? LoopRepeat : LoopOnce,
      loopAnimation ? Infinity : 1,
    );
    activeAction.play();
    advancing.current = false;
    invalidate();
    activeAction.paused = !playback.current.animationPlaying;
    activeAction.setEffectiveTimeScale(playback.current.animationSpeed);
    return () => {
      activeAction.stop();
    };
  }, [activeAction, animation, loopAnimation, invalidate]);

  useEffect(() => {
    if (!activeAction) return;
    activeAction.paused = !animationPlaying;
    activeAction.setEffectiveTimeScale(animationSpeed);
    advancing.current = false;
    invalidate();
  }, [activeAction, animationPlaying, animationSpeed, invalidate]);

  useEffect(() => {
    if (!activeAction || animationResetToken === 0) return;
    activeAction.reset().play();
    advancing.current = false;
    invalidate();
    activeAction.paused = !playback.current.animationPlaying;
  }, [activeAction, animationResetToken, invalidate]);

  return (
    <>
      <primitive
        object={model}
        onClick={(event: import("@react-three/fiber").ThreeEvent<MouseEvent>) => {
          event.stopPropagation();
          onSelectMesh(event.object.userData.viewerNodeId ?? null);
        }}
      />
      {selectedObject && createPortal(<SelectionOutline />, selectedObject)}
    </>
  );
}

function ViewerMaterial({
  shading,
  color = "#a7aaa5",
}: {
  shading: ViewerShading;
  color?: string;
}) {
  if (shading === "normals") return <meshNormalMaterial />;
  if (shading === "wireframe")
    return <meshBasicMaterial color="#34483f" wireframe />;
  return (
    <meshStandardMaterial
      color={shading === "solid" ? "#a7aaa5" : color}
      roughness={shading === "solid" ? 0.82 : 0.68}
      metalness={0}
    />
  );
}

function SelectionOutline() {
  return (
    <Outlines
      name="Viewer selection outline"
      color="#f2a93b"
      thickness={3}
      toneMapped={false}
    />
  );
}

"use client";

import { CameraControls, CameraControlsImpl } from "@react-three/drei";
import { useFrame, useThree } from "@react-three/fiber";
import { useCallback, useEffect, useRef, type RefObject } from "react";
import {
  Vector3,
  type Group,
  type PerspectiveCamera as ThreePerspectiveCamera,
  type OrthographicCamera as ThreeOrthographicCamera,
} from "three";
import { frameBounds } from "./model-inspection";
import type { ViewerCameraStore } from "./model-viewer-camera";
import type { ViewerCameraPreset, ViewerCameraState, ViewerLighting } from "./model-viewer-types";

const presetVectors: Record<ViewerCameraPreset, [number, number, number]> = {
  isometric: [1.7, 1.15, 1.7],
  front: [0, 0, 1],
  right: [1, 0, 0],
  back: [0, 0, -1],
  left: [-1, 0, 0],
  top: [0.001, 1, 0.001],
  bottom: [0.001, -1, 0.001],
};

export function CameraRig({
  lighting,
  objectRef,
  fitVersion,
  preset,
  resetToken,
  autoRotate,
  autoRotateSpeed,
  onCameraChange,
  cameraStore,
  paneSelector,
  fixed,
}: {
  lighting: ViewerLighting;
  fixed: boolean;
  paneSelector: string;
  objectRef: RefObject<Group | null>;
  fitVersion: number;
  preset: ViewerCameraPreset;
  resetToken: number;
  autoRotate: boolean;
  autoRotateSpeed: number;
  onCameraChange?: (state: ViewerCameraState) => void;
  cameraStore?: ViewerCameraStore;
}) {
  const controls = useRef<CameraControlsImpl | null>(null);
  const invalidate = useThree((state) => state.invalidate);
  const camera = useThree(
    (state) => state.camera as ThreePerspectiveCamera | ThreeOrthographicCamera,
  );
  const size = useThree((state) => state.size);

  const frameObject = useCallback(
    (transition: boolean) => {
      const object = objectRef.current;
      if (!object || !controls.current) return;
      const { center, radius, distance, near, far } = frameBounds(
        object,
        size.width / size.height,
        "fov" in camera ? camera.fov : 42,
      );
      camera.near = near;
      camera.far = far;
      camera.updateProjectionMatrix();
      if ("isOrthographicCamera" in camera)
        void controls.current.zoomTo(
          Math.min(size.width, size.height) / (radius * 2.3),
          false,
        );
      const direction = new Vector3(
        ...(lighting === "outside" && preset === "isometric"
          ? [1.7, 0.5, 1.7] as const
          : presetVectors[preset]),
      ).normalize();
      const position = center.clone().add(direction.multiplyScalar(distance));
      controls.current.minDistance = radius * 0.05;
      controls.current.maxDistance = distance * 10;
      void controls.current.setLookAt(
        position.x,
        position.y,
        position.z,
        center.x,
        center.y,
        center.z,
        transition,
      );
      if (!transition) controls.current.saveState();
    },
    [camera, lighting, objectRef, preset, size.width, size.height],
  );

  useEffect(() => {
    frameObject(false);
  }, [fitVersion, frameObject, size.width, size.height]);
  useEffect(() => {
    if (resetToken > 0) frameObject(true);
  }, [resetToken, frameObject]);

  useEffect(() => {
    if (!cameraStore) return;
    cameraStore.register((view, transition) => {
      void controls.current?.setLookAt(
        ...view.position,
        ...view.target,
        transition,
      );
      // Imperative commands do not cause a React render. Wake the demand loop
      // so controls apply the new position and publish the live camera view.
      invalidate();
    });
    const current = controls.current;
    if (current) cameraStore.publish({
      position: current.getPosition(new Vector3()).toArray(),
      target: current.getTarget(new Vector3()).toArray(),
    });
    return () => cameraStore.register(null);
  }, [cameraStore, invalidate]);

  useFrame((_, delta) => {
    if (autoRotate && controls.current)
      controls.current.rotate(autoRotateSpeed * delta, 0, false);
  });

  function readCamera(): ViewerCameraState | null {
    if (!controls.current) return null;
    const position = controls.current.getPosition(new Vector3());
    const target = controls.current.getTarget(new Vector3());
    return { position: position.toArray(), target: target.toArray() };
  }

  function reportLiveCamera() {
    const view = readCamera();
    if (view) cameraStore?.publish(view);
  }

  function reportCamera() {
    const view = readCamera();
    if (view) onCameraChange?.(view);
  }

  const actions = CameraControlsImpl.ACTION;
  const orthographic = "isOrthographicCamera" in camera;
  return (
    <CameraControls
      ref={controls}
      domElement={
        document.querySelector<HTMLElement>(paneSelector) ?? undefined
      }
      makeDefault
      smoothTime={0.25}
      dollyToCursor
      onChange={reportLiveCamera}
      onRest={reportCamera}
      azimuthRotateSpeed={fixed ? 0 : 1}
      polarRotateSpeed={fixed ? 0 : 1}
      mouseButtons={{
        left: fixed ? actions.TRUCK : actions.ROTATE,
        right: actions.TRUCK,
        middle: orthographic ? actions.ZOOM : actions.DOLLY,
        wheel: orthographic ? actions.ZOOM : actions.DOLLY,
      }}
      touches={{
        one: fixed ? actions.TOUCH_TRUCK : actions.TOUCH_ROTATE,
        two: orthographic
          ? actions.TOUCH_ZOOM_TRUCK
          : actions.TOUCH_DOLLY_TRUCK,
        three: actions.TOUCH_TRUCK,
      }}
    />
  );
}

export function FitStaticCamera({
  objectRef,
  fitVersion,
  preset,
  resetToken,
}: {
  objectRef: RefObject<Group | null>;
  fitVersion: number;
  preset: ViewerCameraPreset;
  resetToken: number;
}) {
  const camera = useThree(
    (state) => state.camera as ThreePerspectiveCamera | ThreeOrthographicCamera,
  );
  const size = useThree((state) => state.size);
  useEffect(() => {
    const object = objectRef.current;
    if (!object) return;
    const { center, radius, distance, near, far } = frameBounds(
      object,
      size.width / size.height,
      "fov" in camera ? camera.fov : 42,
    );
    const direction = new Vector3(...presetVectors[preset]).normalize();
    camera.position.copy(center).add(direction.multiplyScalar(distance));
    camera.near = near;
    camera.far = far;
    if ("isOrthographicCamera" in camera)
      camera.zoom = Math.min(size.width, size.height) / (radius * 2.3);
    camera.lookAt(center);
    camera.updateProjectionMatrix();
  }, [
    camera,
    fitVersion,
    objectRef,
    preset,
    resetToken,
    size.width,
    size.height,
  ]);
  return null;
}

export function DragLook({ selector }: { selector: string }) {
  const { camera, invalidate } = useThree();
  useEffect(() => {
    const target = document.querySelector<HTMLElement>(selector);
    if (!target) return;
    let dragging = false;
    camera.rotation.reorder("YXZ");
    target.tabIndex = 0;
    const down = (event: globalThis.PointerEvent) => {
      if (event.button === 0) {
        dragging = true;
        target.focus();
        target.setPointerCapture(event.pointerId);
      }
    };
    const move = (event: globalThis.PointerEvent) => {
      if (!dragging) return;
      camera.rotation.y -= event.movementX * 0.002;
      camera.rotation.x = Math.max(
        -Math.PI / 2 + 0.05,
        Math.min(
          Math.PI / 2 - 0.05,
          camera.rotation.x - event.movementY * 0.002,
        ),
      );
      invalidate();
    };
    const up = (event: globalThis.PointerEvent) => {
      dragging = false;
      if (target.hasPointerCapture(event.pointerId))
        target.releasePointerCapture(event.pointerId);
    };
    target.addEventListener("pointerdown", down);
    target.addEventListener("pointermove", move);
    target.addEventListener("pointerup", up);
    target.addEventListener("pointercancel", up);
    return () => {
      target.removeEventListener("pointerdown", down);
      target.removeEventListener("pointermove", move);
      target.removeEventListener("pointerup", up);
      target.removeEventListener("pointercancel", up);
    };
  }, [camera, invalidate, selector]);
  return null;
}

export function FirstPersonMovement({
  requirePointerLock,
  selector,
}: {
  requirePointerLock: boolean;
  selector: string;
}) {
  const { camera, gl, invalidate } = useThree();
  const pressed = useRef(new Set<string>());
  useEffect(() => {
    const target = document.querySelector<HTMLElement>(selector);
    const down = (event: KeyboardEvent) => {
      if (
        (event.target as HTMLElement)?.closest(
          "input, textarea, select, [contenteditable]",
        )
      )
        return;
      if (!requirePointerLock && event.target !== target) return;
      if (requirePointerLock && document.pointerLockElement !== gl.domElement)
        return;
      pressed.current.add(event.code);
      invalidate();
      if (
        (document.pointerLockElement || !requirePointerLock) &&
        (event.code.startsWith("Arrow") || event.code === "Space")
      )
        event.preventDefault();
    };
    const up = (event: KeyboardEvent) => pressed.current.delete(event.code);
    const blur = () => pressed.current.clear();
    window.addEventListener("keydown", down);
    window.addEventListener("keyup", up);
    window.addEventListener("blur", blur);
    return () => {
      window.removeEventListener("keydown", down);
      window.removeEventListener("keyup", up);
      window.removeEventListener("blur", blur);
    };
  }, [requirePointerLock, selector, gl, invalidate]);
  useFrame((_, delta) => {
    const target = document.querySelector<HTMLElement>(selector);
    if (
      requirePointerLock
        ? document.pointerLockElement !== gl.domElement
        : document.activeElement !== target
    )
      return;
    const speed = Math.min(delta, 0.05) * 2.2;
    const keys = pressed.current;
    const forward =
      Number(keys.has("KeyW") || keys.has("ArrowUp")) -
      Number(keys.has("KeyS") || keys.has("ArrowDown"));
    const sideways =
      Number(keys.has("KeyD") || keys.has("ArrowRight")) -
      Number(keys.has("KeyA") || keys.has("ArrowLeft"));
    const vertical =
      Number(keys.has("Space") || keys.has("KeyE")) -
      Number(
        keys.has("ShiftLeft") || keys.has("ShiftRight") || keys.has("KeyQ"),
      );
    if (!forward && !sideways && !vertical) return;
    const scale = 1 / Math.hypot(forward, sideways, vertical);
    camera.translateZ(-forward * speed * scale);
    camera.translateX(sideways * speed * scale);
    camera.position.y += vertical * speed * scale;
    invalidate();
  });
  return null;
}

"use client";

import { useEffect, useRef, type RefObject } from "react";

const inertLocks = new WeakMap<HTMLElement, { count: number; previous: boolean }>();
const scrollLocks = new WeakMap<Document, { count: number; previous: string }>();
const focusable = 'button, a[href], input, select, textarea, [tabindex], [contenteditable="true"]';

/** Contain the fallback fullscreen viewer without remounting its canvas. */
export function useExpandedViewerFocus(
  ref: RefObject<HTMLDivElement | null>,
  expanded: boolean,
  returnFocus: RefObject<HTMLElement | null>,
  onClose: () => void,
) {
  const close = useRef(onClose);
  close.current = onClose;
  useEffect(() => {
    const root = ref.current;
    if (!expanded || !root) return;
    const doc = root.ownerDocument;
    const previousFocus = returnFocus.current;
    let lastFocus: HTMLElement = root;
    const locks = scrollLocks.get(doc) ?? { count: 0, previous: doc.body.style.overflow };
    locks.count++;
    scrollLocks.set(doc, locks);
    doc.body.style.overflow = "hidden";
    const inertElements = new Set<HTMLElement>();
    const portals = new Map<HTMLElement, { position: string; zIndex: string }>();

    // Base UI menus and tooltips are portaled. Follow their ARIA ownership
    // instead of treating every document-level popup as part of this viewer.
    function insideElements() {
      const inside = new Set<HTMLElement>([root!]);
      for (const element of inside) {
        for (const trigger of element.querySelectorAll('[aria-controls], [aria-describedby]')) {
          const ids = `${trigger.getAttribute("aria-controls") ?? ""} ${trigger.getAttribute("aria-describedby") ?? ""}`;
          for (const id of ids.split(/\s+/).filter(Boolean)) {
            const popup = doc.getElementById(id);
            const portal = popup?.closest<HTMLElement>("[data-base-ui-portal]");
            if (portal) inside.add(portal);
          }
        }
      }
      return [...inside];
    }
    function tabbables() {
      return insideElements().flatMap((element) => [...element.querySelectorAll<HTMLElement>(focusable)])
        .filter((element) => element.tabIndex >= 0 && !element.matches(":disabled") &&
          !element.closest("[inert]") && element.getClientRects().length > 0 &&
          getComputedStyle(element).visibility !== "hidden");
    }
    function releaseInert() {
      for (const element of inertElements) {
        const lock = inertLocks.get(element)!;
        if (--lock.count === 0) {
          element.inert = lock.previous;
          inertLocks.delete(element);
        }
      }
      inertElements.clear();
    }
    function isolate() {
      releaseInert();
      const inside = insideElements();
      for (const portal of inside.slice(1)) {
        if (!portals.has(portal)) portals.set(portal, { position: portal.style.position, zIndex: portal.style.zIndex });
        portal.style.position = "relative";
        portal.style.zIndex = "101";
      }
      function visit(parent: HTMLElement) {
        for (const child of parent.children) {
          if (!(child instanceof HTMLElement) || inside.includes(child)) continue;
          if (inside.some((element) => child.contains(element))) visit(child);
          else {
            const lock = inertLocks.get(child) ?? { count: 0, previous: child.inert };
            lock.count++;
            inertLocks.set(child, lock);
            inertElements.add(child);
            child.inert = true;
          }
        }
      }
      visit(doc.body);
    }
    function containFocus(event: FocusEvent) {
      const target = event.target;
      if (target instanceof HTMLElement && insideElements().some((element) => element.contains(target))) {
        lastFocus = target;
      } else {
        (lastFocus.isConnected && !lastFocus.closest("[inert]") ? lastFocus : root!).focus({ preventScroll: true });
      }
    }
    function keyDown(event: KeyboardEvent) {
      if (event.defaultPrevented) return;
      if (event.key === "Tab") {
        const elements = tabbables();
        const index = elements.indexOf(doc.activeElement as HTMLElement);
        if (!elements.length || (event.shiftKey ? index <= 0 : index === -1 || index === elements.length - 1)) {
          event.preventDefault();
          (event.shiftKey ? elements.at(-1) ?? root! : elements[0] ?? root!).focus();
        }
      }
    }
    function escape(event: KeyboardEvent) {
      if (event.key !== "Escape") return;
      // Menus get the first Escape. Tooltips must not consume the viewer's
      // escape action merely because a toolbar button currently has focus.
      if (insideElements().some(element => [...element.querySelectorAll('[role="menu"], [role="listbox"], [role="dialog"]')]
        .some(popup => popup.getClientRects().length > 0 && !popup.hasAttribute("data-closed")))) return;
      event.preventDefault();
      event.stopPropagation();
      close.current();
    }
    isolate();
    if (previousFocus && root.contains(previousFocus)) lastFocus = previousFocus;
    else (tabbables()[0] ?? root).focus({ preventScroll: true });
    doc.addEventListener("focusin", containFocus);
    doc.addEventListener("keydown", keyDown);
    doc.addEventListener("keydown", escape, true);
    const observer = new MutationObserver(isolate);
    observer.observe(doc.body, { subtree: true, childList: true, attributes: true, attributeFilter: ["aria-controls", "aria-describedby"] });
    return () => {
      observer.disconnect();
      doc.removeEventListener("focusin", containFocus);
      doc.removeEventListener("keydown", keyDown);
      doc.removeEventListener("keydown", escape, true);
      releaseInert();
      for (const [portal, style] of portals) Object.assign(portal.style, style);
      if (--locks.count === 0) {
        doc.body.style.overflow = locks.previous;
        scrollLocks.delete(doc);
      }
      if (previousFocus?.isConnected) previousFocus.focus({ preventScroll: true });
    };
  }, [expanded, ref, returnFocus]);
}

"use client";
import { useCallback, useState } from "react";

/** Controlled/default/onChange triplet; the third item resets the uncontrolled value silently. */
export function useControlledState<T>(
  controlled: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (value: T) => void, (value: T) => void] {
  const [internal, setInternal] = useState(defaultValue);
  const value = controlled === undefined ? internal : controlled;
  const setValue = useCallback(
    (next: T) => {
      if (controlled === undefined) setInternal(next);
      onChange?.(next);
    },
    [controlled, onChange],
  );
  return [value, setValue, setInternal];
}

"use client";
import type { RefObject } from "react";
import { viewerBackgroundColor } from "./model-viewer-colors";
import type { ViewerLighting } from "./model-viewer-types";
import type { ReportFeedback } from "./use-viewer-feedback";

/** PNG copy/download of the composited canvas over the lighting background. */
export function useViewerCapture({
  canvasRef,
  canCapture,
  lighting,
  fileName,
  report,
}: {
  canvasRef: RefObject<HTMLCanvasElement | null>;
  canCapture: boolean;
  lighting: ViewerLighting;
  fileName: string;
  report: ReportFeedback;
}) {
  return async function capture(action: "copy" | "download") {
    const canvas = canvasRef.current;
    if (!canCapture || !canvas) return;
    try {
      const source = document.createElement("canvas");
      source.width = canvas.width;
      source.height = canvas.height;
      const context = source.getContext("2d");
      if (!context) throw new Error("The viewer could not create a PNG.");
      context.fillStyle = viewerBackgroundColor(lighting);
      context.fillRect(0, 0, source.width, source.height);
      context.drawImage(canvas, 0, 0);
      const image = new Promise<Blob>((resolve, reject) => {
        source.toBlob(
          (blob) =>
            blob
              ? resolve(blob)
              : reject(new Error("The viewer could not create a PNG.")),
          "image/png",
        );
      });
      if (action === "copy") {
        if (!navigator.clipboard?.write || typeof ClipboardItem === "undefined")
          throw new Error(
            "Image clipboard access is unavailable. Download the PNG instead.",
          );
        await navigator.clipboard.write([
          new ClipboardItem({ "image/png": image }),
        ]);
        report("Screenshot copied to clipboard.");
      } else {
        const blob = await image;
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = `${
          fileName
            .replace(/[^a-z0-9-_]+/gi, "-")
            .replace(/^-|-$/g, "")
            .slice(0, 80) || "model-view"
        }.png`;
        link.click();
        setTimeout(() => URL.revokeObjectURL(url), 60_000);
        report("Screenshot downloaded as PNG.");
      }
    } catch (error) {
      report(
        error instanceof Error ? error.message : "Could not capture the view.",
        true,
      );
    }
  };
}

"use client";
import { useCallback, useEffect, useRef, useState } from "react";

export type ViewerFeedback = { message: string; error: boolean };
export type ReportFeedback = (message: string, error?: boolean) => void;

/** Short-lived status message shown in the viewer's status part. */
export function useViewerFeedback() {
  const [feedback, setFeedback] = useState<ViewerFeedback | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const clearTimer = () => {
    if (timer.current) clearTimeout(timer.current);
    timer.current = null;
  };
  useEffect(() => clearTimer, []);
  const report = useCallback<ReportFeedback>((message, error = false) => {
    setFeedback({ message, error });
    clearTimer();
    timer.current = setTimeout(() => setFeedback(null), 4500);
  }, []);
  const clearFeedback = useCallback(() => {
    clearTimer();
    setFeedback(null);
  }, []);
  return { feedback, report, clearFeedback };
}

"use client";
import { useEffect, useRef, useState, type RefObject } from "react";
import { useExpandedViewerFocus } from "./use-expanded-viewer-focus";
import type { ReportFeedback } from "./use-viewer-feedback";

/** Native fullscreen with an in-page expanded fallback when the browser refuses entry. */
export function useViewerFullscreen(
  viewerRef: RefObject<HTMLDivElement | null>,
  report: ReportFeedback,
) {
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const returnFocus = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const update = () => {
      const active = document.fullscreenElement === viewerRef.current;
      setIsFullscreen(active);
      if (active) setIsExpanded(false);
    };
    document.addEventListener("fullscreenchange", update);
    return () => document.removeEventListener("fullscreenchange", update);
  }, [viewerRef]);

  useExpandedViewerFocus(viewerRef, isExpanded, returnFocus, () => setIsExpanded(false));

  async function toggleFullscreen() {
    if (isExpanded) {
      setIsExpanded(false);
      return;
    }
    const viewer = viewerRef.current;
    if (viewer && document.fullscreenElement === viewer) {
      // A failed exit leaves native fullscreen active; never stack the fallback on top of it.
      try {
        await document.exitFullscreen();
      } catch {
        report("Could not exit fullscreen. Press Escape to leave it.", true);
      }
      return;
    }
    returnFocus.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    try {
      if (!document.fullscreenEnabled || !viewer)
        throw new Error("Fullscreen unavailable");
      await viewer.requestFullscreen();
    } catch {
      if (document.fullscreenElement !== viewer) setIsExpanded(true);
    }
  }

  return { fullscreen: isFullscreen || isExpanded, isExpanded, toggleFullscreen };
}

"use client";
import { useEffect, useState, type RefObject } from "react";

/** True while the viewer is scrolled out of view or the page is hidden. */
export function useViewerHidden(viewerRef: RefObject<HTMLElement | null>) {
  const [inViewport, setInViewport] = useState(true);
  const [pageVisible, setPageVisible] = useState(true);
  useEffect(() => {
    const update = () => setPageVisible(document.visibilityState !== "hidden");
    update();
    document.addEventListener("visibilitychange", update);
    const observer = typeof IntersectionObserver === "undefined"
      ? null
      : new IntersectionObserver(([entry]) => setInViewport(entry.isIntersecting));
    if (viewerRef.current) observer?.observe(viewerRef.current);
    return () => {
      document.removeEventListener("visibilitychange", update);
      observer?.disconnect();
    };
  }, [viewerRef]);
  return !inViewport || !pageVisible;
}

export function useReducedMotion(enabled: boolean) {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    if (!enabled) {
      setReduced(false);
      return;
    }
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, [enabled]);
  return reduced;
}

import type { ModelInspection } from "./model-inspection";

type Node = ModelInspection["nodes"][number];
const parentPath = (id: string) => id.slice(0, Math.max(0, id.lastIndexOf("/")));

/** Index parent paths once; searches walk each matching ancestor at most once. */
export function indexHierarchy(nodes: Node[]) {
  const parents = new Map<string, string>();
  const branches = new Set<string>();
  const names = new Map<string, string>();
  for (const node of nodes) {
    const parent = parentPath(node.id);
    parents.set(node.id, parent);
    branches.add(parent);
    names.set(node.id, node.name.toLowerCase());
  }
  return {
    branches,
    visible(query: string, collapsed: ReadonlySet<string>): Node[] {
      const normalized = query.toLowerCase();
      if (normalized) {
        const matching = new Set<string>();
        for (const node of nodes) {
          if (!names.get(node.id)!.includes(normalized)) continue;
          let id: string | undefined = node.id;
          while (id && !matching.has(id)) {
            matching.add(id);
            id = parents.get(id) ?? parentPath(id);
          }
        }
        return nodes.filter((node) => matching.has(node.id));
      }
      // Memoize hidden ancestry; standalone consumers need not sort parents
      // before children, and collapsed paths may refer to omitted groups.
      const hidden = new Map<string, boolean>();
      return nodes.filter((node) => {
        const chain: string[] = [];
        let id = node.id;
        let result = false;
        while (id) {
          if (hidden.has(id)) { result = hidden.get(id)!; break; }
          chain.push(id);
          const parent = parents.get(id) ?? parentPath(id);
          if (collapsed.has(parent)) { result = true; break; }
          id = parent;
        }
        for (const child of chain) hidden.set(child, result);
        return !result;
      });
    },
  };
}

